const express=require('express');
const session=require('express-session');
const Database=require('better-sqlite3');
const bcrypt=require('bcryptjs');

const app=express();
const PORT=process.env.PORT||3000;
const db=new Database('results.db');

app.use(express.json());
app.use(express.urlencoded({extended:true}));
app.use(session({secret:process.env.SESSION_SECRET||'elpc-change-this-secret',resave:false,saveUninitialized:false,cookie:{httpOnly:true,sameSite:'lax'}}));

const HTML='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ELPC Student Results</title><link rel="stylesheet" href="style.css"></head><body><header><div class="brand"><img src="/logo.png" alt="ELPC Logo"><div><b>ELPC</b><span> Easy Learn Physics Classes</span></div></div><button id="adminBtn">Admin</button></header><main><section class="hero"><h1>Student Result Portal</h1><p>Enter your Roll Number to view your result.</p><div class="search"><input id="roll" placeholder="Enter Roll Number"><button onclick="findResult()">View Result</button></div><div id="result"></div></section><section id="admin" class="admin hidden"><div class="panel" id="login"><h2>Admin Login</h2><input id="user" placeholder="Admin ID" value="admin"><input id="pass" type="password" placeholder="Password"><button onclick="login()">Login</button><p class="hint">First login: admin / admin123</p></div><div class="panel hidden" id="dashboard"><div class="dashhead"><h2>Admin Dashboard</h2><div><button onclick="changePassword()">Change Password</button><button onclick="logout()">Logout</button></div></div><div class="form"><input id="sid" type="hidden"><input id="sroll" placeholder="Roll No"><input id="sname" placeholder="Student Name"><input id="physics" type="number" placeholder="Physics"><input id="chemistry" type="number" placeholder="Chemistry"><input id="math" type="number" placeholder="Math"><input id="english" type="number" placeholder="English"><input id="hindi" type="number" placeholder="Hindi"><button id="saveBtn" onclick="saveStudent()">Save Student</button><button onclick="clearForm()">Clear</button></div><div class="tablewrap"><table><thead><tr><th>Roll</th><th>Name</th><th>Physics</th><th>Chemistry</th><th>Math</th><th>English</th><th>Hindi</th><th>Actions</th></tr></thead><tbody id="students"></tbody></table></div></div></section></main><script src="app.js"></script></body></html>\n';
const CSS='*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f4f7fb;color:#172033}header{height:64px;background:#101828;color:white;display:flex;align-items:center;justify-content:space-between;padding:0 6%;font-size:18px}header b{font-size:25px;color:#55d6be}button{border:0;border-radius:8px;padding:11px 17px;background:#1769e0;color:#fff;font-weight:700;cursor:pointer}header button{background:#55d6be;color:#071a16}main{max-width:1100px;margin:auto;padding:35px 18px}.hero{background:white;border-radius:18px;padding:42px 25px;text-align:center;box-shadow:0 8px 30px #00000010}.hero h1{font-size:38px;margin:0 0 8px}.search{display:flex;max-width:600px;margin:25px auto 0;gap:10px}.search input,input{width:100%;padding:12px;border:1px solid #ccd4df;border-radius:8px;font-size:15px}.admin{margin-top:28px}.hidden{display:none}.panel{background:white;border-radius:15px;padding:24px;box-shadow:0 8px 30px #0000000d}.panel input{margin:6px 0}.hint{color:#667085;font-size:13px}.dashhead{display:flex;justify-content:space-between;align-items:center;gap:10px}.dashhead div{display:flex;gap:8px}.form{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:20px 0}.form button{margin-top:4px}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:850px}th,td{padding:10px;border-bottom:1px solid #e5e7eb;text-align:left;font-size:14px}th{background:#f8fafc}.actions button{padding:6px 9px;margin-right:4px}.resultcard{max-width:800px;margin:25px auto 0;text-align:left;border:1px solid #e5e7eb;border-radius:12px;padding:20px}.marks{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-top:15px}.mark{background:#f8fafc;padding:12px;border-radius:8px}.total{font-size:20px;margin-top:15px;font-weight:700}@media(max-width:700px){.hero h1{font-size:29px}.search{flex-direction:column}.form{grid-template-columns:1fr 1fr}.dashhead{align-items:flex-start;flex-direction:column}.marks{grid-template-columns:1fr 1fr}}\n\n.brand-header{padding:18px 20px}.brand{display:flex;align-items:center;gap:14px}.logo{width:72px;height:72px;object-fit:contain;border-radius:50%;background:#000}.brand h1{margin:0;font-size:clamp(20px,5vw,30px)}.brand p{margin:3px 0 0;opacity:.8}.card{overflow:hidden}\n.brand{display:flex;align-items:center;gap:10px}.brand img{width:46px;height:46px;object-fit:contain;border-radius:50%}\n';
const JS='const $=id=>document.getElementById(id);$(\'adminBtn\').onclick=()=>{$(\'admin\').classList.toggle(\'hidden\');$(\'admin\').scrollIntoView({behavior:\'smooth\'})};\nasync function findResult(){let r=$(\'roll\').value.trim();if(!r)return;let box=$(\'result\');box.innerHTML=\'Searching...\';let x=await fetch(\'/api/result/\'+encodeURIComponent(r));let d=await x.json();if(!x.ok){box.innerHTML=\'<div class="resultcard">❌ \'+d.error+\'</div>\';return}box.innerHTML=`<div class="resultcard"><h2>${d.name}</h2><p><b>Roll No:</b> ${d.roll}</p><div class="marks"><div class="mark">Physics<br><b>${d.physics}</b></div><div class="mark">Chemistry<br><b>${d.chemistry}</b></div><div class="mark">Math<br><b>${d.math}</b></div><div class="mark">English<br><b>${d.english}</b></div><div class="mark">Hindi<br><b>${d.hindi}</b></div></div><div class="total">Total: ${d.total} / 500 &nbsp; | &nbsp; Percentage: ${d.percentage}% &nbsp; | &nbsp; ${d.status}</div></div>`}\nasync function login(){let x=await fetch(\'/api/login\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({username:$(\'user\').value,password:$(\'pass\').value})});let d=await x.json();if(!x.ok)return alert(d.error);$(\'login\').classList.add(\'hidden\');$(\'dashboard\').classList.remove(\'hidden\');loadStudents()}\nasync function loadStudents(){let x=await fetch(\'/api/students\');if(!x.ok)return;let a=await x.json();$(\'students\').innerHTML=a.map(s=>`<tr><td>${s.roll}</td><td>${s.name}</td><td>${s.physics}</td><td>${s.chemistry}</td><td>${s.math}</td><td>${s.english}</td><td>${s.hindi}</td><td class="actions"><button onclick=\'editStudent(${JSON.stringify(s)})\'>Edit</button><button onclick=\'deleteStudent(${s.id})\'>Delete</button></td></tr>`).join(\'\')}\nfunction editStudent(s){$(\'sid\').value=s.id;$(\'sroll\').value=s.roll;$(\'sname\').value=s.name;$(\'physics\').value=s.physics;$(\'chemistry\').value=s.chemistry;$(\'math\').value=s.math;$(\'english\').value=s.english;$(\'hindi\').value=s.hindi}\nfunction clearForm(){[\'sid\',\'sroll\',\'sname\',\'physics\',\'chemistry\',\'math\',\'english\',\'hindi\'].forEach(i=>$(i).value=\'\')}\nasync function saveStudent(){let body={roll:$(\'sroll\').value,name:$(\'sname\').value,physics:$(\'physics\').value,chemistry:$(\'chemistry\').value,math:$(\'math\').value,english:$(\'english\').value,hindi:$(\'hindi\').value};if(!body.roll||!body.name)return alert(\'Roll number and name required\');let id=$(\'sid\').value;let x=await fetch(id?\'/api/students/\'+id:\'/api/students\',{method:id?\'PUT\':\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify(body)});let d=await x.json();if(!x.ok)return alert(d.error);clearForm();loadStudents()}\nasync function deleteStudent(id){if(!confirm(\'Delete this student?\'))return;await fetch(\'/api/students/\'+id,{method:\'DELETE\'});loadStudents()}\nasync function logout(){await fetch(\'/api/logout\',{method:\'POST\'});location.reload()}\nasync function changePassword(){let p=prompt(\'New password (minimum 6 characters):\');if(!p)return;let x=await fetch(\'/api/change-password\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({password:p})});let d=await x.json();alert(x.ok?\'Password changed successfully\':d.error)}\n';
const LOGO=Buffer.from('','base64');

db.exec(`CREATE TABLE IF NOT EXISTS admin(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password_hash TEXT);
CREATE TABLE IF NOT EXISTS students(id INTEGER PRIMARY KEY AUTOINCREMENT,roll TEXT UNIQUE NOT NULL,name TEXT NOT NULL,physics REAL DEFAULT 0,chemistry REAL DEFAULT 0,math REAL DEFAULT 0,english REAL DEFAULT 0,hindi REAL DEFAULT 0,updated_at TEXT DEFAULT CURRENT_TIMESTAMP);`);
if(!db.prepare('SELECT 1 FROM admin LIMIT 1').get()) db.prepare('INSERT INTO admin(username,password_hash) VALUES(?,?)').run('admin',bcrypt.hashSync('admin123',10));

function auth(req,res,next){if(req.session.admin)return next();res.status(401).json({error:'Unauthorized'});}
app.get('/',(req,res)=>res.type('html').send(HTML));
app.get('/style.css',(req,res)=>res.type('text/css').send(CSS));
app.get('/app.js',(req,res)=>res.type('application/javascript').send(JS));
app.get('/logo.png',(req,res)=>res.type('png').send(LOGO));
app.get('/api/result/:roll',(req,res)=>{const s=db.prepare('SELECT * FROM students WHERE roll=?').get(req.params.roll.trim());if(!s)return res.status(404).json({error:'Result not found'});const total=s.physics+s.chemistry+s.math+s.english+s.hindi;const percentage=total/5;res.json({...s,total,percentage:percentage.toFixed(2),status:percentage>=33?'PASS':'FAIL'});});
app.post('/api/login',(req,res)=>{const a=db.prepare('SELECT * FROM admin WHERE username=?').get(req.body.username);if(!a||!bcrypt.compareSync(req.body.password,a.password_hash))return res.status(401).json({error:'Invalid ID or password'});req.session.admin={id:a.id,username:a.username};res.json({ok:true});});
app.post('/api/logout',auth,(req,res)=>req.session.destroy(()=>res.json({ok:true})));
app.get('/api/me',(req,res)=>res.json({admin:req.session.admin||null}));
app.get('/api/students',auth,(req,res)=>res.json(db.prepare('SELECT * FROM students ORDER BY roll').all()));
app.post('/api/students',auth,(req,res)=>{try{const x=req.body;const st=db.prepare(`INSERT INTO students(roll,name,physics,chemistry,math,english,hindi) VALUES(?,?,?,?,?,?,?)`).run(x.roll,x.name,+x.physics||0,+x.chemistry||0,+x.math||0,+x.english||0,+x.hindi||0);res.json({ok:true,id:st.lastInsertRowid});}catch(e){res.status(400).json({error:e.message.includes('UNIQUE')?'Roll number already exists':e.message});}});
app.put('/api/students/:id',auth,(req,res)=>{try{const x=req.body;if(!x.roll||!x.name)return res.status(400).json({error:'Roll number and name required'});const r=db.prepare(`UPDATE students SET roll=?,name=?,physics=?,chemistry=?,math=?,english=?,hindi=?,updated_at=CURRENT_TIMESTAMP WHERE id=?`).run(x.roll.trim(),x.name.trim(),+x.physics||0,+x.chemistry||0,+x.math||0,+x.english||0,+x.hindi||0,req.params.id);if(!r.changes)return res.status(404).json({error:'Student not found'});res.json({ok:true});}catch(e){res.status(400).json({error:e.message.includes('UNIQUE')?'Roll number already exists':e.message});}});
app.delete('/api/students/:id',auth,(req,res)=>{db.prepare('DELETE FROM students WHERE id=?').run(req.params.id);res.json({ok:true});});
app.post('/api/change-password',auth,(req,res)=>{if(!req.body.password||req.body.password.length<6)return res.status(400).json({error:'Password must be at least 6 characters'});db.prepare('UPDATE admin SET password_hash=? WHERE id=?').run(bcrypt.hashSync(req.body.password,10),req.session.admin.id);res.json({ok:true});});

app.listen(PORT,()=>console.log(`ELPC Results Portal running on ${PORT}`));
